<?php session_start(); require_once "../config/database.php"; $username = $_POST['username'] ?? ''; $password = $_POST['password'] ?? ''; if ($username === '' || $password === '') { die("Username and password are required."); } $stmt = $pdo->prepare( "SELECT * FROM users WHERE username = ?" ); $stmt->execute([$username]); $user = $stmt->fetch(PDO::FETCH_ASSOC); if ($user && password_verify($password, $user['password'])) { $_SESSION['user_id'] = $user['id']; $_SESSION['username'] = $user['username']; $_SESSION['role'] = $user['role']; header("Location: ../dashboard.php"); exit; } die("Invalid username or password."); ?>